head.script:
// 테스트 설명, 유효성 값 설정
//  ★ iframe 컴포넌트는 disabled 상태를 실질적으로 지원하지 않는다.
//    · setDisabled() 는 iframe 에서 no-op(@hidden) 이고, disabled="true" 로 생성해도 실제 입력/포커스/이벤트
//      차단 없이 내부 플래그만 남는다. → getDisabled() 가 초기 로딩 후 항상 false 를 반환하는 것만 일관되게 검증한다.
//    · iframe 자체는 onclick 이벤트를 지원하지 않지만(oniframeload / oniframeunload 만 지원), 별도 w2:button 의
//      onclick 으로 target1.getDisabled() 를 호출하는 것은 정상이므로 [getDisabled] 버튼 트리거로 검증한다.
//    · iframe 은 dynamicCreate 시 inline src 를 주면 _dynamicCreateAfter 가 미로딩 contentDocument 접근으로 TypeError.
//      → src 없이 생성 후 setSrc() 로 내부 페이지를 설정한다. (reference_iframe_dynamic_setsrc_not_inline)
scwin.tData = {
    "description" : "[iframe > M > getDisabled]<br/>컴포넌트에 적용된 비활성화(disabled) 상태값을 반환합니다.",
    "validation" : [
        "비활성화(disabled) 상태를 true/false 로 반환하여야 합니다.",
        "비활성화(disabled) 상태이면 컴포넌트에 대한 입력, 포커스, 이벤트 등이 차단되어야 합니다."
    ]
}



scwin.onpageload = async function () {
    // comp 초기 생성 (비동기 dynamicCreate / setSrc 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] iframe 컴포넌트는 disabled 상태를 실질적으로 지원하지 않습니다. 본 샘플은 getDisabled() 가 초기 로딩 후 false 를 반환하는 것만 검증합니다."', '', 'label1');

    // iframe(target1) 생성 : inline src 금지 → src 없이 dynamicCreate 후 setSrc 로 내용 표시.
    //  (reference_iframe_dynamic_setsrc_not_inline)
    let strTarget = '<w2:iframe ' + strNameSpace + ' id="target1" style="width:500px; height:300px; border:1px solid #cccccc;"></w2:iframe>';
    scwin.target1 = await $p.dynamicCreate("target1", "iframe", strTarget, grp_comp);
    scwin.target1.setSrc("/sample/common_link/iframe_link_1.xml");
}



// [getDisabled] 버튼 클릭 : iframe 은 disabled 미지원이므로 초기 상태 false 를 반환한다.
scwin.btn_getDisabled_onclick = function (e) {
    let rtn = scwin.target1.getDisabled();
    wf_body_bottom.getObj("scwin").setReturnValue("getDisabled() 반환값 : " + rtn);
};
